export const trustWithdrawDisbursement = <ThrowOnError extends boolean = false>(options: Options<TrustWithdrawDisbursementData, ThrowOnError>): RequestResult<TrustWithdrawDisbursementResponses, TrustWithdrawDisbursementErrors, ThrowOnError> => (options.client ?? client).post<TrustWithdrawDisbursementResponses, TrustWithdrawDisbursementErrors, ThrowOnError>({
    url: '/api/v1/trust/disbursement-requests/{requestId}/withdrawal',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns the firm's disbursement-authorization posture — whether money leaving a client ledger takes a second person (off, above a threshold amount, or always) and whether whoever authorizes it must hold the authority capability — together with every version the firm has ever written. A firm that has never written one has the shipped default: always two-person, no authority requirement.
 */
export const trustReadAuthorizationPolicy = <ThrowOnError extends boolean = false>(options?: Options<TrustReadAuthorizationPolicyData, ThrowOnError>): RequestResult<TrustReadAuthorizationPolicyResponses, TrustReadAuthorizationPolicyErrors, ThrowOnError> => (options?.client ?? client).get<TrustReadAuthorizationPolicyResponses, TrustReadAuthorizationPolicyErrors, ThrowOnError>({ url: '/api/v1/trust/authorization-policy', ...options });

/**
 * Changes the firm's disbursement-authorization posture, as a new immutable version recording who changed it, when, and from what. The change governs NEW authorizations only: a request already pending keeps the policy version it was submitted under, in both directions. Requires the authority capability — relaxing how the firm's client money moves is itself an act of authority over it.
 */
export const trustChangeAuthorizationPolicy = <ThrowOnError extends boolean = false>(options: Options<TrustChangeAuthorizationPolicyData, ThrowOnError>): RequestResult<TrustChangeAuthorizationPolicyResponses, TrustChangeAuthorizationPolicyErrors, ThrowOnError> => (options.client ?? client).put<TrustChangeAuthorizationPolicyResponses, TrustChangeAuthorizationPolicyErrors, ThrowOnError>({
    url: '/api/v1/trust/authorization-policy',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Moves trust funds between two matters of the SAME client. No bank movement happens, so no bank line is posted and no reconciliation item is created. A destination matter belonging to a different client is refused.
 */
export const trustTransferBetweenMatters = <ThrowOnError extends boolean = false>(options: Options<TrustTransferBetweenMattersData, ThrowOnError>): RequestResult<TrustTransferBetweenMattersResponses, TrustTransferBetweenMattersErrors, ThrowOnError> => (options.client ?? client).post<TrustTransferBetweenMattersResponses, TrustTransferBetweenMattersErrors, ThrowOnError>({
    url: '/api/v1/trust/matter-transfers',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one matter's trust ledger: its stored balance, the amount under disputed-funds holds, what is available, and every movement that touched it in effective-date order. A transfer between two matters appears on both.
 */
export const trustMatterLedger = <ThrowOnError extends boolean = false>(options: Options<TrustMatterLedgerData, ThrowOnError>): RequestResult<TrustMatterLedgerResponses, TrustMatterLedgerErrors, ThrowOnError> => (options.client ?? client).get<TrustMatterLedgerResponses, TrustMatterLedgerErrors, ThrowOnError>({ url: '/api/v1/trust/matters/{matterId}/ledger', ...options });

/**
 * Lists the bank statements recorded for one trust account, most recent period first — what a member picks from when starting a reconciliation.
 */
export const trustListBankStatements = <ThrowOnError extends boolean = false>(options: Options<TrustListBankStatementsData, ThrowOnError>): RequestResult<TrustListBankStatementsResponses, TrustListBankStatementsErrors, ThrowOnError> => (options.client ?? client).get<TrustListBankStatementsResponses, TrustListBankStatementsErrors, ThrowOnError>({ url: '/api/v1/trust/bank-statements', ...options });

/**
 * Records one period of a trust bank account as the institution reported it, with its lines, in one atomic write. This is the only external input the trust subsystem has: an item the firm never recorded — a bank fee, a returned deposit, a forged check — exists nowhere in the platform until it arrives here. Balances are signed, because a trust bank account really can be overdrawn. A statement is never edited; a bank that reissues a period is recorded as a new statement naming the one it supersedes.
 */
export const trustRecordBankStatement = <ThrowOnError extends boolean = false>(options: Options<TrustRecordBankStatementData, ThrowOnError>): RequestResult<TrustRecordBankStatementResponses, TrustRecordBankStatementErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordBankStatementResponses, TrustRecordBankStatementErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one statement's lines in the order the bank posted them.
 */
export const trustBankStatementLines = <ThrowOnError extends boolean = false>(options: Options<TrustBankStatementLinesData, ThrowOnError>): RequestResult<TrustBankStatementLinesResponses, TrustBankStatementLinesErrors, ThrowOnError> => (options.client ?? client).get<TrustBankStatementLinesResponses, TrustBankStatementLinesErrors, ThrowOnError>({ url: '/api/v1/trust/bank-statements/{statementId}/lines', ...options });

/**
 * Reads a statement file the firm exported from its bank and reports what is in it: the column mapping it resolved, every row it could read and what each would become, every row it could not and why, and the totals. NOTHING IS STORED — running this is not a decision to import anything, and the report is often the reason to decide. The date convention is stated by the caller and never detected: a date this endpoint cannot read is a reported row, never a date reinterpreted under another convention.
 */
export const trustPreviewStatementImport = <ThrowOnError extends boolean = false>(options: Options<TrustPreviewStatementImportData, ThrowOnError>): RequestResult<TrustPreviewStatementImportResponses, TrustPreviewStatementImportErrors, ThrowOnError> => (options.client ?? client).post<TrustPreviewStatementImportResponses, TrustPreviewStatementImportErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements/import/preview',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Records a statement from a file that was previewed and confirmed. The file is re-read here rather than taken from the preview, and the fingerprint the preview returned must still match it — so a file that changed between being reviewed and being agreed to is refused rather than stored. The response reports what was actually recorded, including how many rows could not be read.
 */
export const trustImportBankStatement = <ThrowOnError extends boolean = false>(options: Options<TrustImportBankStatementData, ThrowOnError>): RequestResult<TrustImportBankStatementResponses, TrustImportBankStatementErrors, ThrowOnError> => (options.client ?? client).post<TrustImportBankStatementResponses, TrustImportBankStatementErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements/import',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Lists the reconciliations recorded for one trust account, most recently opened first. A closed one carries the proof it froze, which is what the firm attested to for that period rather than what is true now.
 */
export const trustListReconciliations = <ThrowOnError extends boolean = false>(options: Options<TrustListReconciliationsData, ThrowOnError>): RequestResult<TrustListReconciliationsResponses, TrustListReconciliationsErrors, ThrowOnError> => (options.client ?? client).get<TrustListReconciliationsResponses, TrustListReconciliationsErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations', ...options });

/**
 * Opens a reconciliation of one recorded bank statement. The trust account is taken from the statement rather than from the caller, so a reconciliation about one account's statement and another account's ledger is not expressible.
 */
export const trustOpenReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustOpenReconciliationData, ThrowOnError>): RequestResult<TrustOpenReconciliationResponses, TrustOpenReconciliationErrors, ThrowOnError> => (options.client ?? client).post<TrustOpenReconciliationResponses, TrustOpenReconciliationErrors, ThrowOnError>({
    url: '/api/v1/trust/reconciliations',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one reconciliation and its three-way proof as it stands NOW: the statement's closing balance adjusted for items the firm recorded that have not reached the bank, the trust bank account's book balance, and the sum of the client ledgers — each as of the statement's period end. When the three do not agree it names which leg is out and by how much; it never forces them into agreement. A closed reconciliation also carries the proof it froze, and the two may differ, which is the ledger having moved since somebody attested to the period.
 */
export const trustGetReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustGetReconciliationData, ThrowOnError>): RequestResult<TrustGetReconciliationResponses, TrustGetReconciliationErrors, ThrowOnError> => (options.client ?? client).get<TrustGetReconciliationResponses, TrustGetReconciliationErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}', ...options });

/**
 * Returns the statement lines this reconciliation has not accounted for, the recorded items it has not accounted for, and the candidate pairings between them with the reasons each is a candidate. NOTHING IS MATCHED BY THIS ENDPOINT, and nothing in the platform matches on its own: a wrong automatic match makes the totals tie out while the ledger and the bank disagree about which events happened, which is the discrepancy a reconciliation exists to find.
 */
export const trustReconciliationSuggestions = <ThrowOnError extends boolean = false>(options: Options<TrustReconciliationSuggestionsData, ThrowOnError>): RequestResult<TrustReconciliationSuggestionsResponses, TrustReconciliationSuggestionsErrors, ThrowOnError> => (options.client ?? client).get<TrustReconciliationSuggestionsResponses, TrustReconciliationSuggestionsErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/suggestions', ...options });

/**
 * Records a member's assertion that one statement line and one recorded ledger entry are the same event. Both ends are named by the caller. The book side is a ledger entry rather than a trust movement because an earned-fee transfer out of trust posts a bank-affecting entry and no movement record, and an item that could never be matched would sit outstanding forever.
 */
export const trustRecordReconciliationMatch = <ThrowOnError extends boolean = false>(options: Options<TrustRecordReconciliationMatchData, ThrowOnError>): RequestResult<TrustRecordReconciliationMatchResponses, TrustRecordReconciliationMatchErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordReconciliationMatchResponses, TrustRecordReconciliationMatchErrors, ThrowOnError>({
    url: '/api/v1/trust/reconciliations/{reconciliationId}/matches',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes back a match a member recorded. Appended rather than deleted — that somebody asserted the pairing and then took it back stays on the record — and the item becomes outstanding again.
 */
export const trustWithdrawReconciliationMatch = <ThrowOnError extends boolean = false>(options: Options<TrustWithdrawReconciliationMatchData, ThrowOnError>): RequestResult<TrustWithdrawReconciliationMatchResponses, TrustWithdrawReconciliationMatchErrors, ThrowOnError> => (options.client ?? client).post<TrustWithdrawReconciliationMatchResponses, TrustWithdrawReconciliationMatchErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/matches/{matchId}/withdrawal', ...options });

/**
 * Closes a reconciliation and freezes what its proof said at that moment. Nothing else is written: no ledger entry, no movement, no correction to anything the proof disagreed with. A period that did NOT balance closes exactly as readily as one that did, recording that it did not tie out and by how much — a record of a problem is the point, and the frozen figures never change afterwards even if a backdated entry moves the live proof.
 */
export const trustCloseReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustCloseReconciliationData, ThrowOnError>): RequestResult<TrustCloseReconciliationResponses, TrustCloseReconciliationErrors, ThrowOnError> => (options.client ?? client).post<TrustCloseReconciliationResponses, TrustCloseReconciliationErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/close', ...options });

/**
 * Returns what is left of the firm's own money in one trust account, with every top-up and every service charge that produced it, most recent first. An account on which the carve-out was never opened has no such balance and answers 404 — the firm's cushion is a thing a firm opts into, never a zero that quietly exists everywhere.
 */
export const trustFirmFundsPosition = <ThrowOnError extends boolean = false>(options: Options<TrustFirmFundsPositionData, ThrowOnError>): RequestResult<TrustFirmFundsPositionResponses, TrustFirmFundsPositionErrors, ThrowOnError> => (options.client ?? client).get<TrustFirmFundsPositionResponses, TrustFirmFundsPositionErrors, ThrowOnError>({ url: '/api/v1/trust/firm-funds', ...options });

/**
 * Opens the bank-charge carve-out on one trust account: the firm may keep its own money in that account for the single purpose of bearing the institution's service charges. It is off until a firm deliberately turns it on, one balance per account, and it carries the same zero floor a client ledger carries — so a charge larger than the firm's own funds aborts rather than reaching client money. Refused outright on a pooled interest-bearing account, which the researched rules exempt from service charges: with no charge for the firm's funds to pay there is no permitted purpose, and firm money in a pooled client account without one is commingling.
 */
export const trustOpenFirmFunds = <ThrowOnError extends boolean = false>(options: Options<TrustOpenFirmFundsData, ThrowOnError>): RequestResult<TrustOpenFirmFundsResponses, TrustOpenFirmFundsErrors, ThrowOnError> => (options.client ?? client).post<TrustOpenFirmFundsResponses, TrustOpenFirmFundsErrors, ThrowOnError>({
    url: '/api/v1/trust/firm-funds',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Puts the firm's own money into the trust account's bank-charge cushion. This is the only way the cushion is funded and the only permitted deposit of firm money into a trust account. It touches the cushion and that account's bank balance and nothing else — a client ledger cannot appear on this entry, because the record of it has no column a client, a matter, or a payee could be named in.
 */
export const trustDepositFirmFunds = <ThrowOnError extends boolean = false>(options: Options<TrustDepositFirmFundsData, ThrowOnError>): RequestResult<TrustDepositFirmFundsResponses, TrustDepositFirmFundsErrors, ThrowOnError> => (options.client ?? client).post<TrustDepositFirmFundsResponses, TrustDepositFirmFundsErrors, ThrowOnError>({
    url: '/api/v1/trust/firm-funds/deposits',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Records the institution taking a service charge out of the trust bank account, borne by the firm's own cushion. A charge larger than the cushion is refused with the remedy named — put the firm's funds in to cover it, then record the charge — because a bank charge is never borne by client money; until then the statement line sits unmatched and the reconciliation reports the difference, which is the honest state. The method is not a field: a service charge is the institution helping itself, which is the one method this movement can carry and is set here rather than stated.
 */
export const trustRecordBankCharge = <ThrowOnError extends boolean = false>(options: Options<TrustRecordBankChargeData, ThrowOnError>): RequestResult<TrustRecordBankChargeResponses, TrustRecordBankChargeErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordBankChargeResponses, TrustRecordBankChargeErrors, ThrowOnError>({
    url: '/api/v1/trust/firm-funds/bank-charges',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * The trust-compliance pack for one trust account over one period: every movement of client money, each client's and each matter's ledger, what the firm attested to at each reconciliation, and every item that did not tie out. Give it a period and a knowledge instant and every figure re-derives from records that can never change, so the same request answers identically however much has been recorded since; omit the knowledge instant and the answer covers everything known now, which is stamped and is not claimed to reproduce. Two blocks are labelled as outside that claim and carry their own instant: the three-way proof shown beside each attestation, and the outstanding items, unmatched statement lines and stored-balance checks in the exceptions section — each is read through the one definition the trust and ledger records already have, and none of those definitions is taken as at a past moment. A period too large to return in one document is refused by name rather than answered short.
 */
export const reportsTrustCompliancePack = <ThrowOnError extends boolean = false>(options: Options<ReportsTrustCompliancePackData, ThrowOnError>): RequestResult<ReportsTrustCompliancePackResponses, ReportsTrustCompliancePackErrors, ThrowOnError> => (options.client ?? client).get<ReportsTrustCompliancePackResponses, ReportsTrustCompliancePackErrors, ThrowOnError>({ url: '/api/v1/reports/trust-compliance/{trustAccountId}', ...options });

/**
 * Lists the client ledgers on one trust account that still hold money and have had no movement since a date the caller states. The date is required and has no default: dormancy is a comparison made at read time, not a stored flag, and the periods that exist differ by jurisdiction and often gate a permission rather than an obligation — so there is no window the platform can pick on a firm's behalf. Each row reports the earliest receipt still on the ledger separately from the last activity, because the conduct rules' clocks run from receipt of the property. Nothing here is a verdict: no row says a balance is abandoned, and the firm may have spoken to that client this morning in a way this platform never saw.
 */
export const trustDormantBalances = <ThrowOnError extends boolean = false>(options: Options<TrustDormantBalancesData, ThrowOnError>): RequestResult<TrustDormantBalancesResponses, TrustDormantBalancesErrors, ThrowOnError> => (options.client ?? client).get<TrustDormantBalancesResponses, TrustDormantBalancesErrors, ThrowOnError>({ url: '/api/v1/trust/unclaimed-funds/dormant-balances', ...options });

/**
 * Opens a diligence file over one client's matter ledger: the record of a firm's efforts to locate the owner of money it is still holding. It stores the observation the reviewer acted on — the balance, the earliest receipt, the last activity — and moves nothing. One ledger carries one open review at a time, because the certification a firm eventually signs is about the whole search and two concurrent files would split the evidence in half.
 */
export const trustOpenUnclaimedFundsReview = <ThrowOnError extends boolean = false>(options: Options<TrustOpenUnclaimedFundsReviewData, ThrowOnError>): RequestResult<TrustOpenUnclaimedFundsReviewResponses, TrustOpenUnclaimedFundsReviewErrors, ThrowOnError> => (options.client ?? client).post<TrustOpenUnclaimedFundsReviewResponses, TrustOpenUnclaimedFundsReviewErrors, ThrowOnError>({
    url: '/api/v1/trust/unclaimed-funds/reviews',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Records one attempt to reach the owner, as it was made: the channel, the date, the address or number actually used, and what came of it. The contact used is required on every channel but a review of the firm's own records — it is the part of the evidence nobody can reconstruct two years later, and a record that says only that the firm wrote to the client is not evidence of anything. Attempts are append-only: one that happened cannot be un-happened, and a correction is a further attempt saying so.
 */
export const trustRecordUnclaimedFundsContactAttempt = <ThrowOnError extends boolean = false>(options: Options<TrustRecordUnclaimedFundsContactAttemptData, ThrowOnError>): RequestResult<TrustRecordUnclaimedFundsContactAttemptResponses, TrustRecordUnclaimedFundsContactAttemptErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordUnclaimedFundsContactAttemptResponses, TrustRecordUnclaimedFundsContactAttemptErrors, ThrowOnError>({
    url: '/api/v1/trust/unclaimed-funds/reviews/{reviewId}/contact-attempts',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Ends one round of diligence, recording what came of it. It writes one row and moves nothing. Closing as a distribution ATTACHES a trust disbursement that has already been composed, authorized under the firm's policy, and committed on the disbursement routes — this endpoint takes no amount, no payee, no effective date and no method, so there is nothing here that could be assembled into a payment, and the movement named must be a disbursement from the very ledger under review. An inconclusive round is closed as a continuing search, which is the honest end of most of them.
 */
export const trustCloseUnclaimedFundsReview = <ThrowOnError extends boolean = false>(options: Options<TrustCloseUnclaimedFundsReviewData, ThrowOnError>): RequestResult<TrustCloseUnclaimedFundsReviewResponses, TrustCloseUnclaimedFundsReviewErrors, ThrowOnError> => (options.client ?? client).post<TrustCloseUnclaimedFundsReviewResponses, TrustCloseUnclaimedFundsReviewErrors, ThrowOnError>({
    url: '/api/v1/trust/unclaimed-funds/reviews/{reviewId}/closure',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one diligence file whole: the observation it was opened on, every locate attempt in the order they were made, and its closure if the round has ended. This is the shape a certification is assembled from, which is why the attempts come back with the review rather than through a second call.
 */
export const trustGetUnclaimedFundsReview = <ThrowOnError extends boolean = false>(options: Options<TrustGetUnclaimedFundsReviewData, ThrowOnError>): RequestResult<TrustGetUnclaimedFundsReviewResponses, TrustGetUnclaimedFundsReviewErrors, ThrowOnError> => (options.client ?? client).get<TrustGetUnclaimedFundsReviewResponses, TrustGetUnclaimedFundsReviewErrors, ThrowOnError>({ url: '/api/v1/trust/unclaimed-funds/reviews/{reviewId}', ...options });

/**
 * Lists invoices newest first, with each one's total, what has been applied to it, and what is still unpaid. The unpaid figure is derived from the per-matter balances rather than stored, so it can never drift from them.
 */
export const billingListInvoices = <ThrowOnError extends boolean = false>(options?: Options<BillingListInvoicesData, ThrowOnError>): RequestResult<BillingListInvoicesResponses, BillingListInvoicesErrors, ThrowOnError> => (options?.client ?? client).get<BillingListInvoicesResponses, BillingListInvoicesErrors, ThrowOnError>({ url: '/api/v1/billing/invoices', ...options });

/**
 * Opens a draft invoice for one client. A draft is a working document: nothing has been asserted to anybody, no number has been drawn, and no work is locked. It becomes a financial record only when it is finalized.
 */
export const billingCreateInvoice = <ThrowOnError extends boolean = false>(options: Options<BillingCreateInvoiceData, ThrowOnError>): RequestResult<BillingCreateInvoiceResponses, BillingCreateInvoiceErrors, ThrowOnError> => (options.client ?? client).post<BillingCreateInvoiceResponses, BillingCreateInvoiceErrors, ThrowOnError>({
    url: '/api/v1/billing/invoices',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Pulls unbilled time and cost entries onto a draft, composing a line from each entry's own snapshot. The entries are CLAIMED, not locked: they stay editable, and they become billed only when the invoice is finalized. An entry another draft already holds is refused, and so is a matter belonging to a different client.
 */
export const billingAddClaims = <ThrowOnError extends boolean = false>(options: Options<BillingAddClaimsData, ThrowOnError>): RequestResult<BillingAddClaimsResponses, BillingAddClaimsErrors, ThrowOnError> => (options.client ?? client).post<BillingAddClaimsResponses, BillingAddClaimsErrors, ThrowOnError>({
    url: '/api/v1/billing/invoices/{invoiceId}/claims',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes one claimed entry back off a draft, returning it to unbilled work-in-progress and removing the line that presented it. The claim record itself remains, released, so that this entry was once on this draft stays answerable.
 */
export const billingReleaseClaim = <ThrowOnError extends boolean = false>(options: Options<BillingReleaseClaimData, ThrowOnError>): RequestResult<BillingReleaseClaimResponses, BillingReleaseClaimErrors, ThrowOnError> => (options.client ?? client).post<BillingReleaseClaimResponses, BillingReleaseClaimErrors, ThrowOnError>({ url: '/api/v1/billing/invoices/{invoiceId}/claims/{claimId}/release', ...options });

/**
 * Edits one line of a draft — its wording, its quantity, its rate, or its amount. This is bill review, and it changes what the CLIENT is told; the time entry the line was composed from is the timekeeper's contemporaneous record of what was done and is left exactly as it was.
 */
export const billingUpdateLine = <ThrowOnError extends boolean = false>(options: Options<BillingUpdateLineData, ThrowOnError>): RequestResult<BillingUpdateLineResponses, BillingUpdateLineErrors, ThrowOnError> => (options.client ?? client).patch<BillingUpdateLineResponses, BillingUpdateLineErrors, ThrowOnError>({
    url: '/api/v1/billing/invoices/{invoiceId}/lines/{lineId}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Throws a draft away, releasing every entry it held back to unbilled work-in-progress. Only a draft can be voided: a finalized invoice is corrected by a credit note, never erased.
 */
export const billingVoidDraft = <ThrowOnError extends boolean = false>(options: Options<BillingVoidDraftData, ThrowOnError>): RequestResult<BillingVoidDraftResponses, BillingVoidDraftErrors, ThrowOnError> => (options.client ?? client).post<BillingVoidDraftResponses, BillingVoidDraftErrors, ThrowOnError>({
    url: '/api/v1/billing/invoices/{invoiceId}/void',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Turns a draft into an evidentiary financial record, in ONE atomic write: the next number in the sequence is drawn, the letterhead and client details are copied onto the invoice, every claimed entry locks as billed, the per-matter balances are created with the ceiling that makes over-application impossible, and the accounts-receivable entry posts. Nothing about the invoice can be edited afterwards. If any part fails, no number is consumed, no work is locked, and nothing is posted. A firm that has not told the platform which of its ledger accounts play the billing roles is refused here, by name, rather than posted somewhere plausible.
 */
export const billingFinalizeInvoice = <ThrowOnError extends boolean = false>(options: Options<BillingFinalizeInvoiceData, ThrowOnError>): RequestResult<BillingFinalizeInvoiceResponses, BillingFinalizeInvoiceErrors, ThrowOnError> => (options.client ?? client).post<BillingFinalizeInvoiceResponses, BillingFinalizeInvoiceErrors, ThrowOnError>({
    url: '/api/v1/billing/invoices/{invoiceId}/finalization',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes earned fees out of a client's trust ledger and puts them against that client's finalized bills, in ONE atomic write: the money leaves the client ledger, arrives in the firm's operating account as two linked entries, and each bill's balance moves by exactly what was applied. A bill that is still a draft, a bill for a different client, a bill that does not charge this matter, or an amount above what this matter still owes on it are each refused by name — money leaves trust for the firm only against a bill that has become an evidentiary record, and there is no override. Applying part of what is owed is ordinary: the rest stays owing and can be applied later. If any part of this fails, no money moves at all.
 */
export const billingApplyTrustFunds = <ThrowOnError extends boolean = false>(options: Options<BillingApplyTrustFundsData, ThrowOnError>): RequestResult<BillingApplyTrustFundsResponses, BillingApplyTrustFundsErrors, ThrowOnError> => (options.client ?? client).post<BillingApplyTrustFundsResponses, BillingApplyTrustFundsErrors, ThrowOnError>({
    url: '/api/v1/billing/trust-applications',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes earned fees out of a client's trust ledger against named finalized invoices, under the firm's own posture — which decides whether this member may take them now or has to ask. A member holding the authority to act on client money, for an amount that needs no second person, takes them in one atomic write and the response says `applied`. Anybody else leaves a pending request with its invoice lines beside it; the response says `pending`, names who can release it, and nothing reaches the ledger. A pending request is checked now so the submitter learns of a problem immediately and re-checked in full at approval, and it is decided under the policy version in force when it was submitted, however the posture changes while it is pending. Rejection and withdrawal use the trust disbursement-request endpoints — the queue is shared.
 */
